/**
 * How Upper and lower knotted butterflies (`joge-no-musubicho`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/joge-no-musubicho";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Mirror the two wings around one narrow body. Place its curled feelers, then turn the same butterfly halfway around to form the central opening.","ja":"細い胴の左右に羽を写し、曲がった触角を置きます。同じ蝶を半回転させ、向かい合わせて中央に空きを残します。"};

export default construction;
export { construction, description };
